]\nprint(\"Design matrix X:\")\nfor row in X:\n    print(row)\n\n# Build X'X matrix\nXtX = [\n    [sum(X[i][0]*X[i][j] for i in range(4)) for j in range(3)],\n    [sum(X[i][1]*X[i][j] for i in range(4)) for j in range(3)],\n    [sum(X[i][2]*X[i][j] for i in range(4)) for j in range(3)]\n]\nprint(\"\\nX'X matrix:\")\nfor row in XtX:\n    print(row)\n\n# Build X'y vector\nXty = [\n    sum(X[i][0]*y[i] for i in range(4)),\n    sum(X[i][1]*y[i] for i in range(4)),\n    sum(X[i][2]*y[i] for i in range(4))\n]\nprint(f\"\\nX'y vector: {Xty}\")\n\n# Solve using Gaussian elimination\ndef solve_linear(A, b):\n    n = len(A)\n    # Create augmented matrix\n    M = [A[i][:] + [b[i]] for i in range(n)]\n    \n    # Forward elimination with partial pivoting\n    for i in range(n):\n        # Find pivot\n        max_row = i\n        for r in range(i+1, n):\n            if abs(M[r][i]) > abs(M[max_row][i]):\n                max_row = r\n        M[i], M[max_row] = M[max_row], M[i]\n        \n        # Make sure diagonal is not zero\n        if abs(M[i][i]) < 1e-12:\n            continue\n        \n        # Eliminate rows below\n        for r in range(i+1, n):\n            factor = M[r][i] / M[i][i]\n            for c in range(i, n+1):\n                M[r][c] -= factor * M[i][c]\n    \n    # Back substitution\n    x = [0.0] * n\n    for i in range(n-1, -1, -1):\n        if abs(M[i][i]) < 1e-12:\n            x[i] = 0.0\n        else:\n            x[i] = M[i][n] - sum(M[i][j] * x[j] for j in range(i+1, n))\n            x[i] /= M[i][i]\n    return x\n\n# Solve for coefficients [a, b, c]\ncoeffs = solve_linear(XtX, Xty)\na, b, c = coeffs\nprint(f\"\\nCoefficients:\")\nprint(f\"a = {a}\")\nprint(f\"b = {b}\")\nprint(f\"c = {c}\")\n\n# Verify by computing fitted values\nprint(\"\\nVerification - fitted values:\")\nfor i, ti in enumerate(t):\n    y_fit = a*ti*ti + b*ti + c\n    print(f\"t={ti}: actual={y[i]}, fitted={y_fit}\")\n\n# Project for t=5 (September 1939)\nt_sep = 5.0\ny_sep = a*